fn extend(
    &mut self,
    triples: impl IntoIterator<Item = Triple>,
    signature_kind: SignatureKind,
) -> Result<()> {
    for triple in triples {
        let Triple {
            message,
            signature_bytes,
            public_key,
        } = triple;

        let signature = Signature::try_from(signature_bytes)?;

        ensure!(
            signature.verify(message, &public_key),
